  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { projects(first: 50, orderBy: name) { nodes { id name description priority priorityName state { name } milestones { id name targetDate } } } }"
  }'

